// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { cn } from "@/lib/utils";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { AreaChart, ChartContainer, ChartLegend, ChartTooltip, ChartTooltipContent, DonutChart, type ChartConfig } from "@/components/ui/chart";
import { formatDay, formatNumber, SOURCES, type Period } from "@/blocks/dashboard-analytics/components/dashboard-analytics-data";
const trafficConfig = {
  visitors: {
    label: "This period" as const,
    color: "var(--chart-1)" as const
  },
  previous: {
    label: "Period before" as const,
    color: "var(--chart-2)" as const
  }
} satisfies ChartConfig;
export const TrafficChart = defineUi<{
  period: Period;
  longName: string;
  className?: string;
}>("TrafficChart", ["period", "longName", "class"], (_props, {
  slots: _slots
}) => {
  const period = computed(() => _props["period"]);
  const longName = computed(() => _props["longName"]);
  const className = computed(() => _props["class"]);
  const data = computed(() => period.value.rows.map((r, i) => ({
    day: r[0],
    visitors: r[1],
    previous: period.value.previous[i]?.[1] ?? null
  })));
  return () => {
    return <Card class={cn("min-w-0", className.value)} seed="analytics-traffic" tape="top" tapeKind="washi-stripes">
      <CardHeader>
        <CardTitle role="heading" aria-level={2}>
          Visitors, day by day
        </CardTitle>
        <CardDescription>Every day in {longName.value}, against the days just before</CardDescription>
      </CardHeader>
      <CardContent>
        <ChartContainer config={trafficConfig} class="aspect-auto h-64 w-full">
          <AreaChart data={data.value} xKey="day" kinds={{
            visitors: "area" as const,
            previous: "line" as const
          }} xFormatter={v => formatDay(String(v))} label={`Visitors per day in ${longName.value}, compared with the period before`} annotations={[{
            at: "max" as const,
            text: "best day" as const,
            series: "visitors" as const
          }]} />
          <ChartTooltip content={<ChartTooltipContent indicator="line" labelFormatter={v => formatDay(String(v))} />} />
          <ChartLegend />
        </ChartContainer>
      </CardContent>
    </Card>;
  };
});
const sourceConfig = {
  search: {
    label: "Search" as const,
    color: "var(--chart-1)" as const
  },
  direct: {
    label: "Direct" as const,
    color: "var(--chart-2)" as const
  },
  social: {
    label: "Social" as const,
    color: "var(--chart-3)" as const
  },
  referral: {
    label: "Referral" as const,
    color: "var(--chart-4)" as const
  },
  email: {
    label: "Email" as const,
    color: "var(--chart-5)" as const
  }
} satisfies ChartConfig;
export const SourcesChart = defineUi<{
  period: Period;
  className?: string;
}>("SourcesChart", ["period", "class"], (_props, {
  slots: _slots
}) => {
  const period = computed(() => _props["period"]);
  const className = computed(() => _props["class"]);
  const data = computed(() => SOURCES.map(s => ({
    source: s.source.toLowerCase(),
    visitors: Math.round(period.value.visitors * s.share)
  })));
  const total = computed(() => data.value.reduce((a, d) => a + d.visitors, 0));
  return () => {
    return <Card class={cn("min-w-0", className.value)} seed="analytics-sources">
      <CardHeader>
        <CardTitle role="heading" aria-level={2}>
          Where they came from
        </CardTitle>
        <CardDescription>Visitors by the door they used</CardDescription>
      </CardHeader>
      <CardContent>
        <ChartContainer config={sourceConfig} class="aspect-auto h-64 w-full">
          <DonutChart data={data.value} nameKey="source" valueKey="visitors" label="Visitors by source" showLabels={false} centerLabel={{
            value: formatNumber(total.value),
            label: "visitors" as const
          }} />
          <ChartTooltip />
          <ChartLegend />
        </ChartContainer>
      </CardContent>
    </Card>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { cn } from "@/lib/utils";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { BarChart, ChartContainer, ChartTooltip, type ChartConfig } from "@/components/ui/chart";
import { Circled } from "@/components/ui/circled";
import { FUNNEL, formatNumber, type Period } from "@/blocks/dashboard-analytics/components/dashboard-analytics-data";
const config = {
  people: {
    label: "People" as const,
    color: "var(--chart-3)" as const
  }
} satisfies ChartConfig;
function biggestDrop() {
  let worst = {
    from: FUNNEL[0].step,
    to: FUNNEL[1].step,
    kept: 1
  };
  for (let i = 1; i < FUNNEL.length; i++) {
    const kept = FUNNEL[i].share / FUNNEL[i - 1].share;
    if (kept < worst.kept) worst = {
      from: FUNNEL[i - 1].step,
      to: FUNNEL[i].step,
      kept
    };
  }
  return worst;
}
export const Funnel = defineUi<{
  period: Period;
  longName: string;
  className?: string;
}>("Funnel", ["period", "longName", "class"], (_props, {
  slots: _slots
}) => {
  const period = computed(() => _props["period"]);
  const longName = computed(() => _props["longName"]);
  const className = computed(() => _props["class"]);
  const data = computed(() => FUNNEL.map(f => ({
    step: f.step,
    people: Math.round(period.value.visitors * f.share)
  })));
  const drop = computed(() => biggestDrop());
  const last = computed(() => FUNNEL[FUNNEL.length - 1]);
  return () => {
    return <Card class={cn("min-w-0", className.value)} seed="analytics-funnel">
      <CardHeader>
        <CardTitle role="heading" aria-level={2}>
          From hello to paid
        </CardTitle>
        <CardDescription>Everyone who visited in {longName.value}, step by step</CardDescription>
      </CardHeader>
      <CardContent>
        <ChartContainer config={config} class="aspect-auto h-64 w-full lg:h-88">
          <BarChart data={data.value} xKey="step" horizontal showValues valueFormatter={formatNumber} label={`Shoppers at each step of the checkout, ${longName.value}`} />
          <ChartTooltip />
        </ChartContainer>
      </CardContent>
      <CardFooter class="flex-col items-start gap-1 text-sm">
        <p>
          Most people slip away between <strong>{drop.value.from.toLowerCase()}</strong> and <strong>{drop.value.to.toLowerCase()}</strong>: only{" "}
          <Circled tone="red" class="mx-1.5">{Math.round(drop.value.kept * 100)}%</Circled> go on.
        </p>
        <p class="text-muted-foreground">{Math.round(last.value.share * 1000) / 10}% of visitors end up paying.</p>
      </CardFooter>
    </Card>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { Card, CardAction, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Sparkline } from "@/components/ui/chart";
import { Icon } from "@/components/ui/icon";
import { change, formatDuration, formatNumber, signed, type Period } from "@/blocks/dashboard-analytics/components/dashboard-analytics-data";
type Stat = {
  id: string;
  label: string;
  value: string;
  delta: number;
  unit: string;
  better: "up" | "down";
  data: number[];
  variant: "line" | "area" | "bar";
};
const SPARK_SLOT = [0, 1, 4, 3];
function statsOf(p: Period): Stat[] {
  return [{
    id: "visitors" as const,
    label: "Visitors" as const,
    value: formatNumber(p.visitors),
    delta: change(p.visitors, p.previousVisitors),
    unit: "%" as const,
    better: "up" as const,
    data: p.rows.map(r => r[1]),
    variant: "line" as const
  }, {
    id: "pageviews" as const,
    label: "Pageviews" as const,
    value: formatNumber(p.pageviews),
    delta: change(p.pageviews, p.previousPageviews),
    unit: "%" as const,
    better: "up" as const,
    data: p.rows.map(r => r[2]),
    variant: "area" as const
  }, {
    id: "bounce" as const,
    label: "Bounce rate" as const,
    value: `${p.bounce}%`,
    delta: Math.round((p.bounce - p.previousBounce) * 10) / 10,
    unit: " pts" as const,
    better: "down" as const,
    data: p.rows.map(r => r[3] / 10),
    variant: "line" as const
  }, {
    id: "session" as const,
    label: "Time on site" as const,
    value: formatDuration(p.session),
    delta: change(p.session, p.previousSession),
    unit: "%" as const,
    better: "up" as const,
    data: p.rows.map(r => r[4]),
    variant: "bar" as const
  }];
}
export const StatCards = defineUi<{
  period: Period;
}>("StatCards", ["period"], (_props, {
  slots: _slots
}) => {
  const period = computed(() => _props["period"]);
  return () => {
    return <section aria-label="Key numbers" class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
      {statsOf(period.value).map((s, i) => {
        const good = s.better === "up" ? s.delta >= 0 : s.delta <= 0;
        return <Card key={s.id} class="@container/card gap-2 py-4" seed={`analytics-stat-${s.id}`}>
            <CardHeader class="gap-0.5">
              <CardDescription>{s.label}</CardDescription>
              <CardTitle class="text-2xl tabular-nums @[280px]/card:text-3xl">{s.value}</CardTitle>
              <CardAction class="pt-1">
                <Sparkline data={s.data} variant={s.variant} slot={SPARK_SLOT[i]} label={`${s.label}, one point per day`} />
              </CardAction>
            </CardHeader>
            <CardFooter class="flex-wrap gap-x-1.5 text-sm text-muted-foreground">
              <span class={good ? "inline-flex items-center gap-1 font-bold text-green" as const : "inline-flex items-center gap-1 font-bold text-red" as const}>
                <Icon name={s.delta >= 0 ? "arrow-up" as const : "arrow-down" as const} size={14} />
                {signed(s.delta, s.unit)}
                <span class="sr-only">{good ? ", better" as const : ", worse" as const}</span>
              </span>
              <span>on the {period.value.days} days before</span>
            </CardFooter>
          </Card>;
      })}
    </section>;
  };
});

